"""Copy method ids and families into the Worker bundle. Run after sandbox/worker/src/taxonomy.py changes."""

import importlib.util
import json
from pathlib import Path

WORKER = Path(__file__).resolve().parent.parent
SOURCE = WORKER.parent.parent / "worker" / "src" / "taxonomy.py"

spec = importlib.util.spec_from_file_location("sandbox_taxonomy", SOURCE)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

methods = {method: entry[0] for method, entry in sorted(module.METHODS.items())}
out = WORKER / "src" / "taxonomy_ids.py"
out.write_text(
    '"""Generated by scripts/sync_taxonomy.py. Do not edit."""\n\n'
    f"METHOD_FAMILY = {json.dumps(methods, indent=4)}\n"
)
print(f"{len(methods)} methods, {len(set(methods.values()))} families")
